SELECT FROM customer WHERE active = true
AND (name LIKE CONCAT('%', #{keyword}, '%') OR email LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE customer
SET name    = #{name},
    email   = #{email},
    phone   = #{phone},
    address = #{address}
